    end
end

--- A point on a line through the origin.
record m.Diagonal
    x: integer
    y: integer

    constructor(at: integer)
        self.x = at
        self.y = at
    end
end

local corner = new m.Diagonal(3)
local origin = new m.Point {x = 0, y = 0}
